        detail: '역 是"车站"，정거장 是"经过的站数"。问"还有几站"用 몇 정거장 남았어요? 或 몇 정거장이에요? 说 몇 역 남았어요 韩国人能猜到意思但不地道。站数 = 정거장/정류장，站本身 = 역/정류장。', detailEn: '역 means "station," while 정거장 is "number of stops passed." To ask "how many stops left," use 몇 정거장 남았어요? or 몇 정거장이에요? Saying 몇 역 남았어요 is understandable but not natural. Stop count = 정거장/정류장; the station itself = 역/정류장.',
