        detail: '关心生病的人不要直译"你还好吗"成 괜찮아요? —— 这在敬语场合会显得随意。对长辈/上级/不熟的人生病，说 괜찮으세요? 加 시 敬语。回答自己"没事"用 괜찮아요，不对自己加 시。', detailEn: 'When caring for someone who\'s sick, don\'t literally translate \'are you okay?\' as 괜찮아요? — it sounds too casual in polite settings. For elders, superiors, or people you don\'t know well, say 괜찮으세요? with the honorific 시. When saying \'I\'m fine\' about yourself, use 괜찮아요 — no 시 for yourself.',
