        turns: [
          { speaker: 'me', korean: '부장님, 그동안 정말 감사했습니다.', chinese: '部长，这段时间真的很感谢您。', chineseEn: 'Director, thank you so much for everything during this time.', note: '"그동안" = 这段时间以来，告别专用', noteEn: '"그동안" = during this time, used for farewells' },
          { speaker: 'them', korean: '아, 벌써 가는구나. 앞으로 잘 지내고, 건강 챙겨요.', chinese: '啊，已经要走了啊。以后多保重，注意身体。', chineseEn: 'Ah, you\'re already leaving. Take good care of yourself from now on, and mind your health.', note: '"~구나" 是长辈对晚辈的感叹语气', noteEn: '"~구나" is an exclamatory tone used by elders to younger people' },
          { speaker: 'me', korean: '네, 부장님도 항상 건강하세요. 종종 연락드리겠습니다.', chinese: '好，部长您也保重身体。我会常联络您。', chineseEn: 'Okay, Director, you take care of your health too. I\'ll keep in touch.', note: '"연락드리다" 是 "연락하다" 的敬语版本', noteEn: '"연락드리다" is the honorific version of "연락하다"' },
          { speaker: 'them', korean: '그래요, 언제든지 놀러 와요. 서운하네요.', chinese: '好，随时来玩。有点舍不得啊。', chineseEn: 'Sure, come by anytime. I\'m a bit sad to see you go.' },
          { speaker: 'me', korean: '저도요. 그럼 이만 가보겠습니다. 안녕히 계세요.', chinese: '我也是。那我先走了，请您留步。', chineseEn: 'Me too. I\'ll head off now, please don\'t see me out.', note: '"안녕히 계세요" 对留下方说；对方对你说 "안녕히 가세요"', noteEn: '"안녕히 계세요" is said to the one staying; they say "안녕히 가세요" to you' },
        ],
