    pitfalls: [
      {
        title: '"안녕히 가세요" vs "안녕히 계세요"',
        detail: '两个都是告别，但方向完全相反：安녕히 "가세요"（请慢走）说给离开的人 —— 你留下、对方走。안녕히 "계세요"（请留步）说给留下的人 —— 你走、对方留。搞错的话对方会愣一下但礼貌上不算失误。都要走用 다음에 봐요/또 만나요。', detailEn: 'Both are farewells, but in opposite directions: 안녕히 "가세요" (go safely) is said to the one leaving — you stay, they go. 안녕히 "계세요" (stay well) is said to the one staying — you go, they stay. If you mix them up, the other person might pause, but it\'s not a politeness mistake. If both are leaving, use 다음에 봐요/또 만나요.',
        wrong: '（我要离开）안녕히 가세요.', wrongEn: '(I\'m leaving) 안녕히 가세요.',
        right: '（我要离开）안녕히 계세요.', rightEn: '(I\'m leaving) 안녕히 계세요.',
      },
      {
        title: '"오빠/언니" 别对不熟的人乱叫', titleEn: 'Don\'t casually use "오빠/언니" with people you don\'t know well',
        detail: '这些是"哥/姐"称呼，只用于比自己大的亲密朋友/恋人/亲哥姐。初次见面直接叫 오빠 会被认为过度亲密（尤其女生叫男生），甚至有暧昧意味。安全叫法：명字 + 씨（○○씨）、职务名（팀장님/선배님）。K-pop 迷叫偶像 오빠 OK，因为是粉丝语境。', detailEn: 'These are "older brother/sister" terms, used only for close friends, lovers, or biological older siblings who are older than you. Calling someone 오빠 on first meeting is seen as overly intimate (especially a woman to a man), even with romantic undertones. Safe options: name + 씨 (○○씨), or title (팀장님/선배님). K-pop fans calling idols 오빠 is fine, since it\'s a fan context.',
        wrong: '（第一次见面）오빠, 이름이 뭐예요?', wrongEn: '(First meeting) 오빠, 이름이 뭐예요?',
        right: '실례지만, 성함이 어떻게 되세요?',
      },
      {
        title: '"밥 먹었어?" 是问候不是邀请', titleEn: '"밥 먹었어?" is a greeting, not an invitation',
        detail: '中国人容易把 밥 먹었어요? 理解成"要不要一起吃饭" —— 实际这是韩国人的问候语（相当于"你好吗"）。回答 네, 먹었어요/아직요 就够，不用真的赴约。反过来 "밥 한번 먹자" (改天一起吃饭吧) 也常常是客套，8 成不会真约。', detailEn: 'Chinese speakers often mistake 밥 먹었어요? for "want to eat together?" — but it\'s actually a Korean greeting (like "how are you?"). Just answer 네, 먹었어요/아직요; no need to actually meet up. Conversely, "밥 한번 먹자" (let\'s eat sometime) is often just politeness — 80% of the time it won\'t happen.',
      },
      {
        title: '第一次见面别问年龄/婚否', titleEn: 'Don\'t ask about age or marital status on first meeting',
        detail: '虽然韩国人自己见面确认年龄很常见（因为敬语系统需要），但外国人第一次见韩国人别直接问 몇 살이에요? —— 会让对方尴尬，尤其对女性/长辈。等对方主动说或问 실례지만 나이가 어떻게 되세요?（不好意思，请问年龄）加敬语缓冲。婚姻状况绝对不问。', detailEn: 'While Koreans often confirm age when meeting (due to the honorific system), foreigners shouldn\'t directly ask 몇 살이에요? on first meeting — it makes the other person uncomfortable, especially women or elders. Wait for them to offer, or ask 실례지만 나이가 어떻게 되세요? (excuse me, may I ask your age?) with polite hedging. Never ask about marital status.',
        wrong: '처음 뵙겠습니다. 몇 살이세요?',
        right: '처음 뵙겠습니다. 잘 부탁드립니다.',
      },
      {
        title: '"잘 부탁드립니다" 是万能收尾', titleEn: '"잘 부탁드립니다" is the all-purpose closer',
        detail: '入职、入学、认识新朋友、房东见面、加入群聊 —— 韩国所有关系开始都用 "잘 부탁드립니다"（请多关照）收尾。这不只是客套，是一种"以后关系拜托你"的社交约定。不说会显得冷漠，说了对方会觉得你懂礼节。发消息自我介绍最后一句也可以加。', detailEn: 'Starting a job, school, meeting new friends, seeing a landlord, joining a group chat — in Korea, every new relationship ends with "잘 부탁드립니다" (please take care of me). It\'s not just politeness; it\'s a social pact of "I\'m entrusting our future relationship to you." Not saying it seems cold; saying it shows you know etiquette. You can add it as the last line of a self-intro message too.',
      },
    ],
