        title: '"좋아하다" vs "좋다" 助词完全不同', titleEn: '"좋아하다" vs "좋다" use completely different particles',
        detail: '좋다（形容词，"好/喜欢"感受）用 이/가：김치가 좋아요（我喜欢泡菜／泡菜好）。좋아하다（动词，"喜欢"行为）用 을/를：김치를 좋아해요（我喜欢泡菜）。告白必须用 좋아하다：너를 좋아해，不是 네가 좋아해。这是最容易翻车的助词坑。', detailEn: '좋다 (adjective, "good/like" feeling) takes 이/가: 김치가 좋아요 (I like kimchi / kimchi is good). 좋아하다 (verb, "to like" action) takes 을/를: 김치를 좋아해요 (I like kimchi). For confessions, you must use 좋아하다: 너를 좋아해, not 네가 좋아해. This is the particle trap that trips everyone up.',
        wrong: '네가 좋아해.',
        right: '너를 좋아해. / 네가 좋아.',
