        title: '스밍 ≠ 그냥 듣기',
        detail: '스밍（streaming）是饭圈专用打榜术语，指按规则反复播放刷榜数据（Melon 每小时算一次、不能锁屏、要循环等）。普通"我在听歌"用 듣고 있어 就够了。混用会显得不专业。', detailEn: '스밍 (streaming) is fandom-specific charting jargon, meaning repeatedly playing to boost stats (Melon counts hourly, no locking screen, loop, etc.). For just "I\'m listening to music," 듣고 있어 is enough. Mixing them up looks unprofessional.',
        wrong: '지금 신곡 스밍 하고 있어.（在浴室随便听）', wrongEn: 'I\'m streaming the new song right now. (casually listening in the bathroom)',
