        detail: '대박 ≈ "绝了/牛了"，是感叹词不是名词。教科书翻译成"大发/成功"但饭圈日常几乎只当感叹用。要形容"爆红"用 대박 났어 / 뜨고 있어，别单说 대박 이에요 那样听着像书面语。', detailEn: '대박 ≈ "awesome/crazy," it\'s an exclamation, not a noun. Textbooks translate it as "big hit/success," but in fandom daily talk it\'s almost only an exclamation. To say "blowing up," use 대박 났어 / 뜨고 있어; don\'t just say 대박 이에요, that sounds bookish.',
