        detail: '숙제 = 日常小作业（背单词、写作业本，小学到大学都用）。과제 = 大型任务/项目作业（大学论文、期末课题）。别用错：숙제 냈어요? 是问日常作业交了吗；과제 냈어요? 是问大 project 交了吗。语言学院/中小学基本只用 숙제，大学两个混用。', detailEn: '숙제 = daily small homework (vocab memorization, workbook, used from elementary to university). 과제 = large task/project assignment (university papers, final projects). Don\'t mix them up: 숙제 냈어요? asks if daily homework was submitted; 과제 냈어요? asks if the big project was submitted. Language institutes and K-12 mostly use only 숙제; universities use both interchangeably.',
