    pitfalls: [
      {
        title: '面试必用 "합니다体"，不用 "아/어요体"', titleEn: 'Use the "합니다" form in interviews, not the "아/어요" form',
        detail: '韩国面试敬语等级最高：안녕하세요 → 안녕하십니까、~예요 → ~입니다、~해요 → ~합니다。面试全程用 합니다体，用 아/어요体（~예요/~해요）会显得不够正式。自我介绍收尾说 감사합니다（合体）不说 감사해요，回答用 ~라고 생각합니다 不用 ~라고 생각해요.', detailEn: 'Korean interview honorifics are highest: 안녕하세요 → 안녕하십니까, ~예요 → ~입니다, ~해요 → ~합니다. Use the 합니다 form throughout the interview; using the 아/어요 form (~예요/~해요) comes across as too casual. End your self-introduction with 감사합니다 (formal), not 감사해요, and answer with ~라고 생각합니다 instead of ~라고 생각해요.',
        wrong: '안녕하세요, 김민지예요.',
        right: '안녕하십니까. 김민지라고 합니다.',
      },
      {
        title: '"연봉" 是年薪不是月薪', titleEn: '"연봉" means annual salary, not monthly salary',
        detail: '연봉 = 一年总薪水（税前），韩国 default 沟通单位。월급 = 月薪。面试报数字必说全年：4천 5백만 원（4500 万韩元/年 ≈ 22 万人民币）。别说月薪数字，面试官会以为你要 5 亿一年。附加福利（보너스/성과급）另算，可问 성과급 시스템 어떻게 되어 있나요?', detailEn: '연봉 = total yearly salary (pre-tax), the default unit in Korea. 월급 = monthly salary. Always state the annual figure in interviews: 4천 5백만 원 (45 million KRW/year ≈ 220,000 RMB). Don\'t give a monthly number, or the interviewer will think you want 500 million a year. Additional benefits (보너스/성과급) are separate; you can ask 성과급 시스템 어떻게 되어 있나요?',
      },
      {
        title: '缺点回答不能说"没有"', titleEn: 'Never say "none" when asked about weaknesses',
        detail: '被问 단점（缺点）说 없어요/딱히 없어요（没有/也没什么）是最大扣分项 —— 面试官会认为你缺自我反省。标准答法：说 1 个"真实但可改进"的缺点 + 附上"目前的改善做法"。经典模板：저는 [缺点]한 성향이 있어서 때때로 [负面影响]합니다. 하지만 요즘은 [改进办法] 하고 있습니다.', detailEn: 'Saying 없어요/딱히 없어요 (none/nothing much) when asked about 단점 (weaknesses) is the biggest deduction — interviewers will think you lack self-reflection. The standard answer: give 1 "real but improvable" weakness + add your "current improvement efforts." Classic template: 저는 [weakness]한 성향이 있어서 때때로 [negative impact]합니다. 하지만 요즘은 [improvement] 하고 있습니다.',
      },
      {
        title: '"~할 수 있어요" 不够正式', titleEn: '"~할 수 있어요" is not formal enough',
        detail: '面试表达能力用 ~할 수 있습니다（合体）比 ~할 수 있어요 更正式。写作也一样：能胜任说 감당할 수 있다고 자신합니다，不写 잘할 수 있어요。想缓和自信语气加 ~라고 생각합니다（我认为）：저는 이 일을 잘 해낼 수 있다고 생각합니다.', detailEn: 'For interview expressions, use ~할 수 있습니다 (formal) — more formal than ~할 수 있어요. Same in writing: say 감당할 수 있다고 자신합니다 for competence, not 잘할 수 있어요. To soften confidence, add ~라고 생각합니다 (I think): 저는 이 일을 잘 해낼 수 있다고 생각합니다.',
      },
      {
        title: '面试完必发感谢邮件', titleEn: 'Always send a thank-you email after an interview',
        detail: '韩国大公司面试后 24 小时内发 감사 메일（感谢邮件）是隐藏加分项。开头：오늘 면접 기회 주셔서 감사드립니다. 중간 提及"1-2 个印象深刻的对话点"，收尾 좋은 소식 기다리겠습니다. 别群发模板，会被识破。中小企业不强求但发了绝不吃亏。', detailEn: 'Sending a 감사 메일 (thank-you email) within 24 hours after an interview at a big Korean company is a hidden plus. Start with: 오늘 면접 기회 주셔서 감사드립니다. Mention "1-2 memorable conversation points" in the middle, and end with 좋은 소식 기다리겠습니다. Don\'t mass-send a template — it\'ll be spotted. Not required for SMEs, but it never hurts.',
      },
    ],
