    pitfalls: [
      {
        title: '"전세" vs "월세" 天差地别', titleEn: '"전세" vs "월세" — worlds apart',
        detail: '韩国租房两大制度：전세 = 一次性交高额押金（房价 50-70%）住 2 年，到期全额退，无月租。월세 = 交小额保证金 + 每月月租（类似中国"押金 + 月租"）。예: 전세 2 亿保证金 vs 월세 1000 万保证金 + 月 50 万。전세 适合有大额存款，월세 适合短住/预算少。别把两者混同 "押一付三"。', detailEn: 'Korea\'s two main rental systems: 전세 = pay a large lump-sum deposit (50-70% of the property price), live for 2 years, get it fully refunded at the end, no monthly rent. 월세 = small deposit + monthly rent (similar to China\'s "deposit + monthly rent"). 예: 전세 200 million deposit vs 월세 10 million deposit + 500,000/month. 전세 suits those with big savings, 월세 suits short stays/limited budgets. Don\'t confuse them with "one month deposit, three months rent."',
      },
      {
        title: '"관리비" 包含内容因房而异', titleEn: '"관리비" contents vary by property',
        detail: '관리비（管理费）韩国房东是"打包收"，但内容差异极大：有的只含电梯/清洁/垃圾（3-5 万），有的包含 인터넷/수도/난방/도시가스（10-15 万）。看房必问 관리비에 뭐가 포함되어 있어요?（管理费含什么？）—— 光看月租便宜有陷阱。', detailEn: 'Management fees in Korea are bundled, but what\'s included varies hugely: some only cover elevator/cleaning/trash (30-50K), others include internet/water/heating/gas (100-150K). Always ask at viewings: 관리비에 뭐가 포함되어 있어요? (What\'s included in the management fee?) — cheap rent alone can be a trap.',
      },
      {
        title: '"층간 소음" 是韩国邻里第一大矛盾', titleEn: '"층간 소음" (floor noise) is the #1 source of neighbor conflict in Korea.',
        detail: '韩国公寓 90% 是钢筋混凝土，隔音差，"층간 소음"（楼层噪音）新闻常上社会版。看房前问 위층에 누가 살아요?（楼上住的谁？）—— 有小孩/宠物慎选。有些新楼是 "층간 소음 방지" 结构，可专门问。签约后邻居噪音投诉走 층간소음 이웃사이센터.', detailEn: 'About 90% of Korean apartments are reinforced concrete with poor soundproofing, and "층간 소음" (floor noise) stories often hit the news. Before viewing, ask 위층에 누가 살아요? (Who lives upstairs?) — be cautious if there are kids/pets. Some newer buildings have "층간 소음 방지" (noise-proof) structures, so ask specifically. After signing, noise complaints go through the 층간소음 이웃사이센터.',
      },
      {
        title: '외국인 签约要额外文件', titleEn: 'Foreigners need extra documents to sign a lease.',
        detail: '外国人租房必须有 외국인 등록증（居留证）或至少长期签证，短期游客不能签正式合同（只能选 airbnb/게스트하우스）。签约要提交护照 + 外登证 + 住址证明。签约必须去 부동산（有牌照的中介）而不是网上直签 —— 走 부동산 才有 계약서（合同书）保护，出问题可通过 대한부동산협회 申诉。', detailEn: 'Foreigners renting must have an 외국인 등록증 (alien registration card) or at least a long-term visa; short-term visitors can\'t sign formal contracts (only Airbnb/guesthouses). To sign, you\'ll need your passport + ARC + proof of address. Always sign through a licensed 부동산 (real estate agent), not directly online — only via a 부동산 do you get the protection of a 계약서 (contract), and issues can be appealed through the 대한부동산협회.',
      },
      {
        title: '"보증금" 到期一定要拿回', titleEn: 'Make sure you get your "보증금" (deposit) back when the lease ends.',
        detail: '保证金退回不是自动的，退房前需：① 签 임대차 계약 종료 통보서（合同终止通告）② 房主验房无损坏 ③ 韩国还有 전입신고（迁入登记，等于中国"落户"）需要撤销。租长期建议做 확정일자（合同盖章公示）—— 房东破产时可优先取回押金。租前学会这几个词能保住百万押金。', detailEn: 'Deposit refunds aren\'t automatic. Before moving out: ① sign an 임대차 계약 종료 통보서 (lease termination notice) ② have the landlord inspect for no damage ③ cancel your 전입신고 (move-in registration, like China\'s hukou). For long-term rentals, get a 확정일자 (contract date stamp) — it gives you priority for your deposit if the landlord goes bankrupt. Learning these terms can protect a million-won deposit.',
      },
    ],
