        detail: '韩国网红生态：나노 인플루언서（1 万粉以下）< 마이크로（1-10 万）< 매크로（10 万-100 万）< 메가/셀럽（100 万以上）。做营销找的 인플루언서 一般是 마이크로/매크로 段。粉丝数 = 팔로워 수，转换率高的是 마이크로（更信任感）。别一律用"网红" 概括 —— 说 셀럽 vs 인플루언서 语感不同。', detailEn: 'Korea\'s influencer ecosystem: 나노 인플루언서 (under 10K followers) < 마이크로 (10K-100K) < 매크로 (100K-1M) < 메가/셀럽 (over 1M). For marketing, you\'d typically target 마이크로/매크로 influencers. Follower count = 팔로워 수, and micro-influencers have higher conversion rates (more trust). Don\'t lump everyone as "网红" — 셀럽 vs 인플루언서 have different nuances.',
