    pitfalls: [
      {
        title: '"좋아해" ≠ "사귀자" —— 阶段完全不同', titleEn: '"Joahae" ≠ "sagwija" — completely different stages',
        detail: '中文说"我喜欢你" 常暗含表白，韩语 좋아해 只是"我喜欢你（作为人/朋友）"，不明确要求交往。想正式确定关系必须说 사귀자/사귈래?（交往吧？）。韩国有"썸 타다"（暧昧期）阶段 —— 互相 좋아해 但没告白也不算情侣。告白必须清晰问对方 사귈래?', detailEn: 'In Chinese, "I like you" often implies a confession, but Korean "joahae" just means "I like you (as a person/friend)" without asking to date. To officially start a relationship, you must say "sagwija/sagwilae?" (Want to date?). Korea has a "ssom tada" (talking stage) — you both like each other but aren\'t a couple until a clear confession. Confess by clearly asking "sagwilae?"',
      },
      {
        title: '"1일" 是恋爱起点，一切纪念日从这数', titleEn: '"1il" is the starting point of a relationship; all anniversaries count from here',
        detail: '韩国情侣关系确定当天叫 "1일"（第 1 天），从此每 100 天一个大坎：22일（22 天）、100일（百日）、200일、300일、500일、1주년（一周年）。忘掉 100일 大概率吵架。第一次告白后立刻互相说 오늘부터 1일이야 是确认关系的仪式感表达。', detailEn: 'The day a Korean couple gets together is called "1il" (Day 1), and from then on, every 100 days is a big milestone: 22il (22 days), 100il (100 days), 200il, 300il, 500il, 1junyeon (first anniversary). Forgetting 100il likely leads to a fight. Right after the first confession, saying "oneulbuteo 1il-iya" to each other is a ritual way to confirm the relationship.',
      },
      {
        title: '"헤어지자" 是分手动词，别翻译为"离别"', titleEn: '"He eojija" is the verb for breaking up — don\'t translate it as "parting"',
        detail: '헤어지다 直译"分开" 用于恋人关系确实是"分手"，但语气冷。想说更柔和用 우리 좀 시간을 갖자（我们要点时间）—— 委婉分手。真彻底分手前很多韩国人先说 잠깐 헤어져 있자（暂时分开一下）作试探。别混淆 헤어지다（分手）和 갈라서다（正式分手，多用于夫妻）。', detailEn: 'He eojida literally means "to separate" and does mean "break up" for couples, but it sounds cold. For something softer, use "uri jom siganeul gajja" (Let\'s take some time) — a gentle breakup. Before a final split, many Koreans first say "jamkkan he eojyeo itja" (Let\'s take a break) as a test. Don\'t confuse he eojida (break up) with galraseoda (formal split, mostly for married couples).',
      },
      {
        title: '"소개팅" 是相亲，"블라인드 데이트" 是外国说法', titleEn: '"Sogaeting" is a blind date; "beulaindeu deiteu" is a foreign term',
        detail: '朋友介绍的相亲对象叫 소개팅（简称"소개+미팅"）—— 韩国 20-30 岁年轻人最主流的认识方式，不像中国"相亲" 带负面色彩。블라인드 데이트 是英语直译，年轻人偶尔用但语感有点老气。相关词：주선자（介绍人）、소개팅앱（相亲 app）、썸녀/썸남（暧昧对象）。', detailEn: 'A blind date set up by friends is called sogaeting (short for "sogae + meeting") — the most common way Koreans in their 20s-30s meet people, without the negative connotation of Chinese "xiangqin." Beulaindeu deiteu is a direct English loan, used occasionally by young people but sounds a bit dated. Related terms: juseonja (matchmaker), sogaetingaep (dating app), ssomnyeo/ssomnam (crush).',
      },
      {
        title: '"자기" 只对恋人用', titleEn: '"Jagi" is only used for a significant other',
        detail: '자기（本意"自己"）在恋爱语境是"亲爱的" —— 韩国情侣间标准昵称，比叫名字更亲密。但仅限恋人/夫妻用，对普通朋友说 자기야 会引起严重误解（暧昧信号）。同样 오빠/누나 对不熟异性慎用。安全叫法：名字 + 아/야（친구 사이）或 씨/님（正式）。', detailEn: 'Jagi (literally "oneself") means "darling" in a romantic context — the standard nickname for Korean couples, more intimate than using names. But it\'s only for lovers/spouses; saying jagiya to a regular friend causes serious misunderstanding (a flirty signal). Similarly, use oppa/nuna cautiously with unfamiliar people. Safe options: name + a/ya (between friends) or ssi/nim (formal).',
      },
    ],
