  pitfalls: [
    {
      title: '票的量词用 장 不用 개', titleEn: 'Use the counter 장 for tickets, not 개',
      detail: '门票、明信片这类薄片状的东西量词用 장（张）。用通用量词 개（个）说 표 두 개 会显得很生硬 —— 记住"纸片类用 장"。', detailEn: 'For flat, thin items like tickets and postcards, use the counter 장. Using the general counter 개 (e.g., 표 두 개) sounds awkward — remember: \'paper-like items take 장.\'',
      wrong: '입장권 두 개 주세요.',
      right: '입장권 두 장 주세요.',
    },
    {
      title: '"预订"和"现场买"分清 예매/구매', titleEn: 'Distinguish between \'reservation\' (예매) and \'buying on the spot\' (구매)',
      detail: '提前网上订票是 예매（预售/预订），到现场买是 현장 구매 或直接说 여기서 사다。把现场买说成 예매 会让工作人员以为你在找取票口 —— 现场买就说 지금 살 수 있어요.', detailEn: 'Booking tickets online in advance is 예매 (advance sale/reservation); buying on the spot is 현장 구매 or simply 여기서 사다. Saying 예매 when you mean to buy on the spot will make staff think you\'re looking for the ticket pickup counter — for on-the-spot purchases, say 지금 살 수 있어요.',
      wrong: '지금 여기서 예매할 수 있어요?',
      right: '지금 여기서 살 수 있어요?',
    },
    {
      title: '请人帮拍照别用命令语气', titleEn: 'Don\'t use a commanding tone when asking someone to take a photo',
      detail: '麻烦陌生人拍照要用客气的 찍어 주시겠어요 或 찍어 주세요，别用生硬的 찍어（拍）或 찍어라。语气太直接会显得没礼貌 —— 拜托别人一定加 주시겠어요/주세요。', detailEn: 'When asking a stranger to take a photo, use polite forms like 찍어 주시겠어요 or 찍어 주세요, not blunt 찍어 (take) or 찍어라. Being too direct sounds rude — always add 주시겠어요/주세요 when making a request.',
      wrong: '사진 찍어.',
      right: '사진 좀 찍어 주시겠어요?',
    },
    {
      title: '指定背景用 (으)로 不用 에서', titleEn: 'Use (으)로 to specify the background, not 에서',
      detail: '"以某物为背景拍"用 배경으로（以…为背景），에서 表示"在某处"。说 남산타워에서 찍어 주세요 意思变成"在南山塔那个位置拍"，语义偏了 —— 指定入镜背景用 배경으로。', detailEn: 'To say \'take a photo with something as the background,\' use 배경으로 (with... as the background). 에서 means \'at a place.\' Saying 남산타워에서 찍어 주세요 means \'take it at Namsan Tower,\' which shifts the meaning — use 배경으로 to specify what appears in the shot.',
      wrong: '남산타워에서 배경 찍어 주세요.',
      right: '남산타워를 배경으로 찍어 주세요.',
    },
    {
      title: '免费别说 공짜 在正式场合', titleEn: 'Don\'t say 공짜 for \'free\' in formal settings',
      detail: '问是否免费入场用 무료（免费）。공짜 虽然也是"免费"但偏口语、略随便，对着售票员或工作人员用 무료 更得体 —— 正式场合优先 무료.', detailEn: 'Use 무료 (free) to ask about free admission. 공짜 also means \'free\' but is more colloquial and casual; 무료 is more appropriate when speaking to ticket sellers or staff — in formal settings, prefer 무료.',
      wrong: '이거 공짜예요?',
      right: '입장이 무료예요?',
    },
  ],
