  pitfalls: [
    {
      title: '住宿的"住"用 묵다 不用 살다', titleEn: 'For \'staying\' at lodging, use 묵다, not 살다',
      detail: '短期住宿、过夜用 묵다（투숙）。살다 是"长期居住/生活"，说 여기서 삼 일 살아요 会让人以为你要在这定居 —— 旅行住几晚一律用 묵다.', detailEn: 'For short stays or overnight, use 묵다 (lodging). 살다 means \'to reside/live long-term\'; saying 여기서 삼 일 살아요 would make people think you\'re settling down here — for a few nights of travel, always use 묵다.',
      wrong: '여기서 삼 일 살 거예요.',
      right: '여기서 삼 박 묵을 거예요.',
    },
    {
      title: '报故障用"안 나와요"不用"없어요"', titleEn: 'To report a malfunction, use \'안 나와요\', not \'없어요\'',
      detail: '热水出不来是设施问题，用 온수가 안 나와요（不出热水）。온수가 없어요 意思是"没有热水（这项配置）"，房东会误解成设施本来就没有 —— 出故障强调"出不来"用 안 나오다.', detailEn: 'No hot water is a facility issue, so say 온수가 안 나와요 (hot water isn\'t coming out). 온수가 없어요 means \'there\'s no hot water (as a feature)\', which the host would misunderstand as the facility never having it — for malfunctions, emphasize \'not coming out\' with 안 나오다.',
      wrong: '온수가 없어요.',
      right: '온수가 안 나와요.',
    },
    {
      title: '寄存行李用 맡기다 不用 보관하다让对方做', titleEn: 'To store luggage, use 맡기다, not 보관하다, when asking someone to do it',
      detail: '请对方帮你存行李用 맡기다（托付/寄存），主语是我。보관하다 是"保管"较书面，口语请求说 짐을 맡길 수 있어요 最自然 —— 说 짐을 보관해 주세요 也懂但生硬。', detailEn: 'To ask someone to store your luggage, use 맡기다 (entrust/store), with \'I\' as the subject. 보관하다 means \'to keep\' and is more formal; in spoken requests, 짐을 맡길 수 있어요 is most natural — 짐을 보관해 주세요 is understood but stiff.',
      wrong: '짐을 지켜 주세요.',
      right: '짐을 맡길 수 있어요?',
    },
    {
      title: '换房间用 바꾸다 不用 옮기다自己搬', titleEn: 'To change rooms, use 바꾸다, not 옮기다, when you\'re not moving it yourself',
      detail: '想请前台给你换房用 방을 바꾸다（换房间）。옮기다 是"搬移（东西/位置）"，说 방을 옮겨 주세요 语义偏向搬动房间本身 —— 换房型/房号用 바꾸다.', detailEn: 'To ask the front desk to change your room, use 방을 바꾸다 (change rooms). 옮기다 means \'to move (things/positions)\', so 방을 옮겨 주세요 leans toward moving the room itself — for changing room type/number, use 바꾸다.',
      wrong: '방을 옮겨 주세요.',
      right: '방을 바꿀 수 있을까요?',
    },
    {
      title: '青旅别默认含早餐', titleEn: 'Don\'t assume hostels include breakfast',
      detail: '민박/게스트하우스 常常不含早餐，订之前要确认 조식 포함이에요（含早餐吗）。直接说 아침 주세요（给我早饭）会显得理所当然又失礼 —— 先用疑问句确认是否包含。', detailEn: 'Minbaks/guesthouses often don\'t include breakfast, so confirm before booking with 조식 포함이에요 (does it include breakfast?). Saying 아침 주세요 (give me breakfast) directly comes off as entitled and rude — first confirm with a question.',
      wrong: '내일 아침 주세요.',
      right: '조식이 포함돼 있어요?',
    },
  ],
