  pitfalls: [
    {
      title: '"被偷"用 도둑맞다，不加 당하다', titleEn: 'For \'stolen,\' use 도둑맞다, not 당하다',
      detail: '도둑맞다 本身就是被动的"被偷"。再加 당하다 说成 도둑맞음을 당했어요 就重复了。直接说 지갑을 도둑맞았어요 即可 —— 主语是"我"，宾语是"被偷的东西"。', detailEn: '도둑맞다 already means \'to be stolen\' in the passive. Adding 당하다 to say 도둑맞음을 당했어요 is redundant. Just say 지갑을 도둑맞았어요 — the subject is \'I\' and the object is \'the thing stolen.\'',
      wrong: '지갑이 도둑을 맞았어요.',
      right: '지갑을 도둑맞았어요.',
    },
    {
      title: '弄丢东西用 잃어버리다 不用 잊어버리다', titleEn: 'For losing things, use 잃어버리다, not 잊어버리다',
      detail: '잃어버리다 是"丢失（物品）"，잊어버리다 是"忘记（事情）"，两个词长得像但意思完全不同。说 여권을 잊어버렸어요 变成"我把护照给忘了"，很奇怪 —— 丢东西一律 잃어버리다.', detailEn: '잃어버리다 means \'to lose (an item),\' while 잊어버리다 means \'to forget (a matter).\' They look similar but mean completely different things. Saying 여권을 잊어버렸어요 becomes \'I forgot my passport,\' which is odd — for losing things, always use 잃어버리다.',
      wrong: '여권을 잊어버렸어요.',
      right: '여권을 잃어버렸어요.',
    },
    {
      title: '韩国报警是112，急救是119', titleEn: 'In Korea, call 112 for police and 119 for emergencies',
      detail: '在韩国报警打112，火灾和急救（叫救护车）打119。别记混，紧急时打错号会耽误时间 —— 抓小偷报案打112，身体出事叫救护车打119。', detailEn: 'In Korea, call 112 to report a crime, and 119 for fires and emergencies (ambulance). Don\'t mix them up — calling the wrong number in an emergency wastes time. Report a theft at 112, and call an ambulance at 119.',
      wrong: '경찰에 신고하려고 119에 전화했어요.',
      right: '경찰에 신고하려고 112에 전화했어요.',
    },
    {
      title: '叫救护车用 부르다 不用 사다', titleEn: 'For calling an ambulance, use 부르다, not 사다',
      detail: '救护车、警察、出租车这类是"呼叫"来的，用 부르다（叫/呼叫）。别用 사다（买）—— 说 구급차를 사 주세요 会变成"请给我买辆救护车"，非常离谱。', detailEn: 'Ambulances, police, and taxis are \'called,\' so use 부르다 (to call). Don\'t use 사다 (to buy) — saying 구급차를 사 주세요 would mean \'Please buy me an ambulance,\' which is absurd.',
      wrong: '구급차를 사 주세요.',
      right: '구급차를 불러 주세요.',
    },
    {
      title: '听不懂先说明再请求慢说', titleEn: 'If you don\'t understand, explain first, then ask them to speak slowly',
      detail: '听不懂时别只反复说 뭐라고요（你说什么），先说明 한국어를 잘 못해요（我韩语不好）再请对方 천천히 말해 주세요（说慢点）。这样对方才知道要放慢、用简单词 —— 铺垫原因比干问更有效。', detailEn: 'When you don\'t understand, don\'t just keep saying 뭐라고요 (what did you say). First explain 한국어를 잘 못해요 (I\'m not good at Korean), then ask them to 천천히 말해 주세요 (speak slowly). That way they\'ll know to slow down and use simple words — explaining why works better than just asking.',
      wrong: '네? 뭐라고요? 뭐라고요?',
      right: '한국어를 잘 못해서 천천히 말해 주세요.',
    },
  ],
