        title: '回应道谢别只会“괜찮아요”', titleEn: 'Don\'t just say \'괜찮아요\' when responding to thanks',
        detail: '别人谢你时，中文习惯说“没事没事”，但韩语里“괜찮아요”更多用于回应道歉。回应感谢应该用“아니에요 / 천만에요 / 별말씀을요”。用错会让对方觉得答非所问。', detailEn: 'When someone thanks you, Chinese speakers tend to say \'没事没事\' (no problem), but in Korean, \'괜찮아요\' is more often used to respond to apologies. To respond to thanks, use \'아니에요 / 천만에요 / 별말씀을요\'. Using the wrong one can make the other person feel you\'re not answering appropriately.',
        wrong: '(对方说 고마워요) 괜찮아요.', wrongEn: '(When they say 고마워요) It\'s okay.',
        right: '(对方说 고마워요) 아니에요, 별거 아니에요.', rightEn: '(When they say 고마워요) No, it\'s nothing.',
