    pitfalls: [
      {
        title: '“예매”和“티켓팅”侧重不同', titleEn: '“예매” and “티켓팅” have different nuances',
        detail: '“예매”是中性词，指提前订票这个行为，电影、火车票都能用；“티켓팅”特指开票瞬间的抢购大战，含“手快才抢得到”的紧张感。演唱会开票那一刻，粉丝说的是“티켓팅”而不是平淡的“예매”。', detailEn: '“예매” is neutral, meaning booking in advance—used for movies, train tickets, etc. “티켓팅” specifically refers to the frantic rush the moment tickets go live, with the tension of “only the fastest get them.” When concert tickets drop, fans say “티켓팅,” not the bland “예매.”',
        wrong: '(形容秒空的抢票) 오늘 콘서트 예매 성공했어요? (语气太平淡)', wrongEn: '(describing a sold-out-in-seconds ticket rush) 오늘 콘서트 예매 성공했어요? (too flat)',
        right: '(形容秒空的抢票) 오늘 콘서트 티켓팅 성공했어요?', rightEn: '(describing a sold-out-in-seconds ticket rush) 오늘 콘서트 티켓팅 성공했어요?',
      },
      {
        title: '“응원봉”和“응원법”不是一回事', titleEn: '“응원봉” and “응원법” are not the same thing',
        detail: '“응원봉”是实体的官方手灯（灯棒），“응원법”是每首歌该喊的固定口号和节奏。说“응원법 챙겼어요?”是错的——口号是背下来的，不是带在身上的。装备用“챙기다”，口号用“외우다（背）”。', detailEn: '“응원봉” is the physical official light stick; “응원법” is the set chants and rhythm for each song. Saying “응원법 챙겼어요?” is wrong—chants are memorized, not carried. Gear uses “챙기다,” chants use “외우다 (memorize).”',
        wrong: '응원법 챙겼어요?',
        right: '응원봉 챙겼어요? 응원법은 미리 외웠어요?',
      },
      {
        title: '“퇴근길”在粉圈不是字面的下班', titleEn: 'In fan circles, “퇴근길” doesn\'t literally mean leaving work',
        detail: '普通语境里“퇴근길”是上班族的下班路，但在追星语境专指演出/行程结束后偶像离场、粉丝在门口相送的场面。跟粉丝说“퇴근길 봤어요”是指看了偶像离场，别理解成偶像去上班了。', detailEn: 'In everyday contexts, “퇴근길” is the commute home for office workers, but in fan culture it specifically refers to the scene where idols leave after a performance/schedule and fans see them off at the entrance. Telling a fan “퇴근길 봤어요” means you saw the idol leaving, not that they went to work.',
        wrong: '(以为偶像要去公司上班) 오빠 퇴근길이라 회사 갔어요?', wrongEn: '(Thinking the idol was going to the office) Since it\'s oppa\'s commute home, did you go to the company?',
        right: '(演出散场看偶像离场) 오늘 퇴근길에서 손 흔들어 줬어요.', rightEn: '(Watching the idol leave after the show) Today at the exit, he waved at me.',
      },
      {
        title: '手段助词“로/으로”按收音选', titleEn: 'The instrumental particle “로/으로” is chosen based on the final consonant',
        detail: '“선예매로 / 정가로”这类表手段的助词，前一个字有收音（ㄹ除外）用“으로”，无收音或以ㄹ收尾用“로”。“선예매”以母音结尾用“로”，若说成“선예매으로”就错了。“카드（卡）”结尾无收音也用“로”。', detailEn: 'For particles like “선예매로 / 정가로” indicating means, if the preceding syllable has a final consonant (except ㄹ), use “으로”; if it has no final consonant or ends in ㄹ, use “로”. “선예매” ends in a vowel, so it takes “로”; saying “선예매으로” would be wrong. “카드 (card)” also has no final consonant, so it takes “로”.',
        wrong: '팬클럽 선예매으로 표를 샀어요.',
        right: '팬클럽 선예매로 표를 샀어요.',
      },
      {
        title: '别把加价转让说成正常“양도”', titleEn: 'Don\'t call a marked-up resale a normal “양도”',
        detail: '“양도”本身指原价转让，是粉圈互助的正常行为；“플미（프리미엄）”是黄牛式加价，粉圈普遍反感甚至抵制。求票时若不写清“정가 양도”，容易被当成能接受加价，最好直接注明“플미 사절”。', detailEn: '“양도” itself means transferring at face value, a normal act of mutual help in fan circles; “플미 (premium)” is scalper-style markup, which fans generally dislike or even boycott. When seeking tickets, if you don\'t clearly write “정가 양도”, you might be assumed to accept markup, so it\'s best to note “플미 사절” directly.',
        wrong: '(想原价求票却只写) 티켓 양도 구해요. (可能收到一堆加价私信)', wrongEn: '(Wanting face-value tickets but only writing) Looking for a ticket transfer. (You might get a bunch of marked-up DMs)',
        right: '(原价求票) 티켓 정가 양도 구해요, 플미 사절입니다.', rightEn: '(Seeking tickets at face value) Looking for a face-value ticket transfer, no premium.',
      },
    ],
