  pitfalls: [
    {
      title: '“알바” 和 “아르바이트” 的场合区别', titleEn: 'The difference in usage between 알바 and 아르바이트',
      detail: '两个词意思一样但语感不同。알바 是口语缩略，朋友间、日常对话里最常用；아르바이트 是完整词，写在招聘启事、简历、正式说明里更合适。面试自我介绍时可以说完整词，聊天时说 알바 就行。别在正式书面里写 알바。', detailEn: 'The two words mean the same thing but feel different. 알바 is a casual abbreviation, most common among friends and in everyday conversation. 아르바이트 is the full word, better for job postings, resumes, and formal explanations. In a self-introduction at an interview, use the full word; in chat, just say 알바. Don\'t write 알바 in formal writing.',
      wrong: '이력서에 "알바 많이 했어요"라고 썼어요.',
      right: '이력서에는 "아르바이트 경험이 많습니다"라고 씁니다.',
    },
    {
      title: '“뛰다” 在打工语境不是“跑步”', titleEn: '뛰다 in a part-time job context doesn\'t mean \'to run\'',
      detail: '대타 뛰다、타임 뛰다 里的 뛰다 意思是“上班、顶班、干这个班”，不是字面的“跑”。中文母语者容易理解成“跑腿”。대타 뛰다 就是顶替别人的班次。记住这是打工圈的固定搭配。', detailEn: 'In 대타 뛰다 and 타임 뛰다, 뛰다 means \'to work, cover a shift, do this shift\'—not literally \'to run.\' Chinese speakers often mistake it for \'running errands.\' 대타 뛰다 means covering someone else\'s shift. Remember this is a fixed phrase in the part-time work world.',
      wrong: '오늘 대타 뛰어서 공원에 갔어요.',
      right: '오늘 친구 대신 대타 뛰어서 6시간 일했어요.',
    },
    {
      title: '辞职别只说 “그만둘래요”', titleEn: 'Don\'t just say 그만둘래요 when quitting',
      detail: '对店长或老板正式提辞职时，해요体的 그만둘래요（我想不干了）听起来太随意、甚至任性。正式场合应该用 그만두겠습니다 或 그만두려고 합니다，并加上 죄송하지만 缓冲。这样既表达了决定，也保持了礼貌。', detailEn: 'When formally resigning to a manager or boss, the 해요-form 그만둘래요 (\'I want to quit\') sounds too casual, even willful. In formal settings, use 그만두겠습니다 or 그만두려고 합니다, and soften it with 죄송하지만. This conveys your decision while staying polite.',
      wrong: '사장님, 저 그만둘래요.',
      right: '사장님, 죄송하지만 이번 달까지만 하고 그만두겠습니다.',
    },
    {
      title: '주휴수당 是法定权利，别放弃', titleEn: '주휴수당 is a legal right—don\'t give it up',
      detail: '주휴수당（周休津贴）是韩国法律规定：每周工作满15小时以上，就能额外拿一天的工钱。很多留学生不知道，被店家含糊过去。签 근로계약서（劳动合同）时确认有没有算 주휴수당，这是应得的，不是老板的恩惠。', detailEn: '주휴수당 (weekly holiday allowance) is mandated by Korean law: if you work 15+ hours a week, you get an extra day\'s pay. Many international students don\'t know this and get brushed off by employers. When signing the 근로계약서 (employment contract), check whether 주휴수당 is included—it\'s your due, not a favor from the boss.',
    },
    {
      title: '시급 收音后接 이 不是 가', titleEn: 'After the final consonant of 시급, use 이, not 가',
      detail: '시급 以收音 ㅂ 结尾，后面主格助词要用 이，不能用 가。同理 월급이、주급이 都用 이。这是助词随收音变化的基本规则：有收音用 이/을/은，无收音用 가/를/는。说 시급가 是典型的初学者错误。', detailEn: '시급 ends with the final consonant ㅂ, so the subject particle must be 이, not 가. Likewise, 월급이 and 주급이 both use 이. This is the basic rule of particles changing with final consonants: with a final consonant use 이/을/은, without one use 가/를/는. Saying 시급가 is a classic beginner mistake.',
      wrong: '시급가 얼마예요?',
      right: '시급이 얼마예요?',
    },
  ],
