  pitfalls: [
    {
      title: '“안 들려요” 和 “못 들어요” 别混', titleEn: 'Don\'t mix up \'안 들려요\' and \'못 들어요\'',
      detail: '设备听不到声音要说 안 들려요（听不见，客观上没声音）。못 들어요 强调“我没能力听/没听成”，用在这里怪怪的。들리다 本身是自动词（声音传到耳朵），所以搭配 안 最自然。反馈故障统一用 소리가 안 들려요。', detailEn: 'If you can\'t hear sound from the device, say 안 들려요 (can\'t hear, objectively no sound). 못 들어요 emphasizes \'I couldn\'t hear/didn\'t get to hear,\' which sounds odd here. 들리다 is an intransitive verb (sound reaching the ear), so pairing it with 안 is most natural. For reporting issues, always use 소리가 안 들려요.',
      wrong: '교수님, 소리를 못 들어요.',
      right: '교수님, 소리가 안 들려요.',
    },
    {
      title: '“링크” 收音后接 좀 而非直接命令', titleEn: 'After \'링크,\' add 좀 instead of using a direct command',
      detail: '让别人发链接时，直接说 링크 보내 (发链接) 太生硬。加 좀 (링크 좀 보내 주세요) 能软化语气，相当于中文“麻烦发一下”。좀 在请求里几乎是必备的润滑剂，别省略。', detailEn: 'When asking someone to send a link, saying 링크 보내 (send the link) directly is too blunt. Adding 좀 (링크 좀 보내 주세요) softens the tone, like saying \'please send it\' in Chinese. 좀 is almost essential as a lubricant in requests—don\'t skip it.',
      wrong: '링크 보내.',
      right: '줌 링크 좀 보내 주세요.',
    },
    {
      title: '“끊기다” 是被动，不要用 “끊어요”', titleEn: '\'끊기다\' is passive—don\'t use \'끊어요\'',
      detail: '网络/声音自己断掉要用被动形 끊기다（소리가 끊겨요）。끊다 是主动“切断”，소리를 끊어요 会变成“我把声音切断”，意思全反了。描述卡顿、掉线一律用 끊기다：소리가 끊겨요、연결이 끊겼어요。', detailEn: 'When the network/sound cuts off on its own, use the passive form 끊기다 (소리가 끊겨요). 끊다 is active \'to cut,\' so 소리를 끊어요 would mean \'I cut the sound,\' completely reversing the meaning. For lag or disconnections, always use 끊기다: 소리가 끊겨요, 연결이 끊겼어요.',
      wrong: '소리를 자꾸 끊어요.',
      right: '소리가 자꾸 끊겨요.',
    },
    {
      title: '“화면 공유” 而不是 “화면 나누기”', titleEn: '\'화면 공유\' not \'화면 나누기\'',
      detail: '共享屏幕的固定说法是 화면 공유。나누다 虽然有“分享/分配”的意思，但 화면 나누기 在软件里指“分屏”，不是把画面共享给别人看。发表时说 화면 공유할게요 才对。', detailEn: 'The standard term for screen sharing is 화면 공유. While 나누다 can mean \'share/divide,\' 화면 나누기 in software refers to \'split screen,\' not sharing your screen with others. When presenting, say 화면 공유할게요.',
      wrong: '화면 나눌게요.',
      right: '화면 공유를 시작할게요.',
    },
    {
      title: '掉线重连别说 “다시 시작해요”', titleEn: 'Don\'t say \'다시 시작해요\' when reconnecting after a disconnect',
      detail: '自己退出会议再进来，自然说法是 나갔다가 다시 들어올게요（先出去再进来）。다시 시작해요（重新开始）听起来像要重开整堂课，会让教授误解。掉线场景固定用 나갔다 오다 / 재접속하다。', detailEn: 'The natural way to say you\'re leaving and re-entering the meeting is 나갔다가 다시 들어올게요 (go out and come back in). 다시 시작해요 (start over) sounds like you\'re restarting the whole class, which could confuse the professor. For disconnection scenarios, always use 나갔다 오다 / 재접속하다.',
      wrong: '수업을 다시 시작할게요.',
      right: '잠깐 나갔다가 다시 들어올게요.',
    },
  ],
