  pitfalls: [
    {
      title: '请求降价用 “~주실 수 있을까요”，别用祈使', titleEn: 'Use “~주실 수 있을까요” to ask for a price cut, not the imperative',
      detail: '商务谈判里让对方降价、让步，直接说 낮춰 주세요（请降价）也能懂，但偏命令。用 낮춰 주실 수 있을까요?（能否为我降一下）加了 시 敬语和 ~ㄹ 수 있을까요 的委婉疑问，姿态更低、更专业。谈判中给对方留余地很重要。', detailEn: 'In business negotiations, saying 낮춰 주세요 (please lower it) to ask for a price cut or concession is understandable but sounds commanding. Using 낮춰 주실 수 있을까요? (Could you lower it for me?) adds the honorific 시 and the polite question ~ㄹ 수 있을까요, making it more humble and professional. Leaving room for the other party is key in negotiations.',
      wrong: '단가 낮춰 주세요.',
      right: '단가를 조금 낮춰 주실 수 있을까요?',
    },
    {
      title: '“조율” 和 “조정” 的细微差别', titleEn: 'The subtle difference between “조율” and “조정”',
      detail: '조율（协调）强调双方沟通、找平衡点，日程/条件/意见 都能 조율；조정（调整）偏单方面把某个数值改动。谈判里“协调交货期”说 납기를 조율하다 更贴切，因为是双方商量。조정 更像“我把价格调低”这种技术性改动。', detailEn: '조율 (coordination) emphasizes two-way communication and finding a balance—schedules, conditions, and opinions can all be 조율. 조정 (adjustment) leans toward unilaterally changing a value. In negotiations, “coordinating the delivery date” is better said as 납기를 조율하다 because it\'s a mutual discussion. 조정 is more like a technical tweak, e.g., “I\'ll lower the price.”',
      wrong: '양측 입장을 조정하고 있습니다.',
      right: '양측 입장을 조율하고 있습니다.',
    },
    {
      title: '“회신드리다” 中 “드리다” 已是谦语', titleEn: 'In “회신드리다,” “드리다” is already humble speech',
      detail: '드리다 本身就是 주다 的谦让语（给尊者），所以 회신드리겠습니다 已经很礼貌。不要再画蛇添足说 회신드려 드리겠습니다 或加多余的敬语。同类还有 연락드리다、전달드리다、문의드리다，一个 드리다 就够。', detailEn: '드리다 is itself the humble form of 주다 (to give to a superior), so 회신드리겠습니다 is already polite. Don\'t overdo it by saying 회신드려 드리겠습니다 or adding extra honorifics. Similar verbs include 연락드리다, 전달드리다, and 문의드리다—one 드리다 is enough.',
      wrong: '검토 후에 회신드려 드리겠습니다.',
      right: '검토 후에 회신드리겠습니다.',
    },
    {
      title: '合同签字：서명 和 날인 不是一回事', titleEn: 'Contract signing: 서명 and 날인 are not the same',
      detail: '서명 是手写签名，날인 是盖章（도장/印章）。韩国正式合同常要求 서명 또는 날인。中文都叫“签”，但如果对方要 날인，只手写签名可能不够，需要盖公司章。看清合同要求的是哪种，别把 날인 也理解成签名。', detailEn: '서명 is a handwritten signature, while 날인 is stamping with a seal (도장). Formal Korean contracts often require 서명 또는 날인. In Chinese, both are called “signing,” but if the other party asks for 날인, a handwritten signature may not suffice—you need to stamp the company seal. Check which one the contract requires; don\'t mistake 날인 for a signature.',
    },
    {
      title: '谈崩说 “결렬”，别用 “실패”', titleEn: 'For talks breaking down, use “결렬,” not “실패”',
      detail: '谈判破裂的专门说法是 협상이 결렬되다。실패（失败）太笼统，也带更强的负面评价色彩，商务场合显得不专业。想表达“希望别谈崩”用 결렬만은 피하고 싶습니다 很地道。', detailEn: 'The specific term for talks breaking down is 협상이 결렬되다. 실패 (failure) is too vague and carries a stronger negative judgment, sounding unprofessional in business. To say “I hope we don\'t hit a deadlock,” 결렬만은 피하고 싶습니다 is very natural.',
      wrong: '협상이 실패됐습니다.',
      right: '협상이 결렬되었습니다.',
    },
  ],
